// Where slice `i` is RIGHT NOW: its region's live base plus the slice's offset. Not
// constexpr, and not HASH_REGIONS[i].base -- that one is frozen at the stock address on
// purpose (see the field comment). A consumer that hashes, dumps or pokes a slice reads
// THIS, which is what stops the determinism oracle hashing bytes nothing writes after a
// region moves (gates can pass vacuously).
inline uint32_t hash_base(int i) { return live_base(HASH_REGIONS[i].rid) + HASH_REGIONS[i].offset; }
#ifndef MH_LIBMH_BUILD // LIB-REF-SPLIT: the stock address, absent standalone
inline uint32_t hash_stock_base(int i) { return HASH_REGIONS[i].base; }
#endif

// ---- the ordered TACTICAL hash manifest (TACT-PREP) --------------------------------------
// The same shape as HASH_REGIONS above and the same append-only order contract, but a
// SEPARATE list on a SEPARATE cadence: seams/harness.cpp hashes these once per llm_tact_frame
// and emits them as a `T` line. Two tables rather than one appended table because mode 6 never
// calls llm_strat_sim_step -- the strategic hook cannot see a tactical frame at all -- and
// because folding the arena into the strategic `combined` hash would let a strategic desync
// report name a region no strategic code touches.
//
// `tile_objects` and `passable` appear in BOTH lists on purpose: they are shared planes that
// tactical uses as scratch and the exit restores from disk (the tactical-probe work Sect. 5).
inline constexpr hash_region TACT_HASH_REGIONS[] = {
    // TACT-PREP piece 2: the TACTICAL hash manifest. A SEPARATE ordered list from `regions`
    // above, and deliberately so. Appending the tactical arena to the strategic manifest would
    // (a) fold ~290 KB of stale arena into every strategic `combined`/`state` hash, so a
    // strategic desync report could name a tactical region that no strategic code touches, and
    // (b) invalidate every recorded golden trajectory. The tactical cadence hook emits its own
    // `T` line over THIS list, on llm_tact_frame rather than llm_strat_sim_step (which mode 6
    // never calls -- docs/tactical-probe.md Sect. 2).
    //
    // SAME ORDER CONTRACT as `regions`: APPEND only. The `T` line is positional.
    {"tact_units", RID_TACT_UNITS, 0u, MH_STOCK_BASE(0x008260d0u), 196596u, false}, // tact_unit_record[129], stride 0x5f4 -- the tactical roster
    {"tact_fx_pool", RID_TACT_FX_POOL, 0u, MH_STOCK_BASE(0x0085b4e0u), 83968u, false}, // llm_tact_fx[1024], stride 0x52 -- projectiles/explosions
    {"tact_doors", RID_TACT_DOOR_TABLE, 0u, MH_STOCK_BASE(0x008742c4u), 1664u, false}, // llm_tact_door[16] -- advanced by llm_tact_door_tick with no input
    {"tact_teleports", RID_TACT_TELEPORT_TABLE, 0u, MH_STOCK_BASE(0x00874950u), 3300u, false}, // llm_tact_teleport[66] -- scanned every frame
    {"tact_char_types", RID_TACT_CHARACTER_TYPES, 0u, MH_STOCK_BASE(0x00873c04u), 1728u, false}, // llm_tact_character_type[16] -- mission-loaded; unit spawn reads .energy to turn the blackboard's hp PERCENT into absolute hp, so it is an input to entry determinism
    {"tact_fx_types", RID_TACT_FX_TYPE_TABLE, 0u, MH_STOCK_BASE(0x00872984u), 4736u, false}, // llm_tact_fx_type[64] -- mission-loaded FX definitions
    {"tact_fov_stencil", RID_TACT_FOV_STENCIL, 0u, MH_STOCK_BASE(0x0082509cu), 4096u, false}, // the FOV raycast stencil -- derived, but it localises a vision divergence one step before the roster shows it
    {"tact_active_unit_count", RID_TACT_ACTIVE_UNIT_COUNT, 0u, MH_STOCK_BASE(0x005590ecu), 4u, false}, // _G_LLM_TACT_ACTIVE_UNIT_COUNT -- also llm_tact_frame's mission-end predicate
    {"tact_active_unit_count_cached", RID_TACT_ACTIVE_UNIT_COUNT_CACHED, 0u, MH_STOCK_BASE(0x005590f0u), 4u, false}, // the per-frame cached copy; a divergence between the two localises a recount bug
    {"tact_squad_size", RID_TACT_SQUAD_SIZE, 0u, MH_STOCK_BASE(0x00559888u), 4u, false}, // how many blackboard slots the mission load consumed
    {"tact_map_width", RID_TACT_MAP_WIDTH_CACHE, 0u, MH_STOCK_BASE(0x00874948u), 4u, false}, // _G_LLM_TACT_MAP_WIDTH_CACHE, written by llm_tact_map_compute_bounds
    {"tact_map_height", RID_TACT_MAP_HEIGHT_CACHE, 0u, MH_STOCK_BASE(0x0087494cu), 4u, false}, // _G_LLM_TACT_MAP_HEIGHT_CACHE
    {"tile_objects", RID_TILE_OBJECTS, 0u, MH_STOCK_BASE(0x00d1ec80u), 524288u, false}, // SHARED plane. Tactical wipes the 128x128 top-left sub-block at the same 256-element stride and the strategic contents are restored from disk on exit (docs/tactical-probe.md Sect. 5) -- hashed here because during a mission this IS tactical occupancy state
    {"passable", RID_PASSABLE, 0u, MH_STOCK_BASE(0x00b64bb0u), 65536u, false}, // SHARED plane, same story as tile_objects. Note it carries MF_VIEW|MF_MEASURED|MF_SAVE but NOT MF_HASH -- the strategic manifest never hashed it, and this is the first list that does
    // THE SIM-ONLY SLICE (TACT-REC, 2026-08-25). Deliberately an ALIAS of tact_units above --
    // the SAME 129 records at the SAME address -- emitted a second time with the render-written
    // animation window marked local(). It exists because tactical animation is RENDER-DRIVEN
    // (docs/tactical-probe.md 9k): llm_tact_unit_update_anim is reached only through
    // llm_tact_render_view's camera-viewport tile scan, and it writes anim_frame_time /
    // frame_index / anim_cycle_time / frame_interval / sprite_id straight into the hashed roster.
    //
    // TWO HASHES RATHER THAN A MASK, and that is the whole point. Masking tact_units would DELETE
    // the signal -- and the leading alternative cause is an occupancy loss in tile_objects, which
    // is sim state, so a mask could hide a real divergence (the same vacuous-gate shape 9e already
    // sprang once). Keeping both means a run can say WHICH: full differs + sim identical =
    // presentation drift; both differ = real. Only the arguable-free fields are dropped;
    // anim_state, progress and cmd_wait_until_time stay IN precisely because they are arguable.
    //
    // EXCLUDED FROM THE COMBINED `T` HASH because its bytes are already in tact_units -- folding
    // it in would double-count, not add coverage. It still occupies its own positional column on
    // the `TR` line and feeds the separate `TS` (sim-only combined) line.
    {"tact_units_sim", RID_TACT_UNITS, 0u, MH_STOCK_BASE(0x008260d0u), 196596u, true}, // ALIAS of tact_units with the render-written animation window local() -- see TACT_ANIM_* in state/region_view.h
};
constexpr int TACT_HASH_REGION_COUNT = 15;

// Named indices, same reasoning as HIDX_* above: an ALIAS slice (one that re-emits another
// slice's bytes under a different traversal) has to be told apart from its source by INDEX, and a
// hand-written constant would drift the moment the table grows.
enum tact_hash_region_index : int {
    TIDX_TACT_UNITS               = 0,
    TIDX_TACT_FX_POOL             = 1,
    TIDX_TACT_DOORS               = 2,
    TIDX_TACT_TELEPORTS           = 3,
    TIDX_TACT_CHAR_TYPES          = 4,
    TIDX_TACT_FX_TYPES            = 5,
    TIDX_TACT_FOV_STENCIL         = 6,
    TIDX_TACT_ACTIVE_UNIT_COUNT   = 7,
    TIDX_TACT_ACTIVE_UNIT_COUNT_CACHED = 8,
    TIDX_TACT_SQUAD_SIZE          = 9,
    TIDX_TACT_MAP_WIDTH           = 10,
    TIDX_TACT_MAP_HEIGHT          = 11,
    TIDX_TILE_OBJECTS             = 12,
    TIDX_PASSABLE                 = 13,
    TIDX_TACT_UNITS_SIM           = 14,
};

